.darma-loader-tw-skeleton-avatar { display: flex; align-items: center; gap: calc(var(--loader-size, 160px) * .07); width: var(--loader-size, 160px); animation: darma-loader-tw-skeleton-avatar-twPulse calc(var(--loader-speed, 1s) * 1.6) cubic-bezier(.4, 0, .6, 1) infinite; }
.darma-loader-tw-skeleton-avatar .darma-loader-tw-skeleton-avatar__avatar { flex: none; width: calc(var(--loader-size, 160px) * .24); height: calc(var(--loader-size, 160px) * .24); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #94a3b8) 42%, transparent); }
.darma-loader-tw-skeleton-avatar .darma-loader-tw-skeleton-avatar__rows { display: flex; flex: 1; flex-direction: column; gap: calc(var(--loader-size, 160px) * .05); }
.darma-loader-tw-skeleton-avatar .darma-loader-tw-skeleton-avatar__rows i { height: calc(var(--loader-size, 160px) * .06); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color, #94a3b8) 26%, transparent); }
.darma-loader-tw-skeleton-avatar .darma-loader-tw-skeleton-avatar__rows i:first-child { width: 88%; }
.darma-loader-tw-skeleton-avatar .darma-loader-tw-skeleton-avatar__rows i:last-child { width: 56%; }
@keyframes darma-loader-tw-skeleton-avatar-twPulse { 50% { opacity: .4; } }

